import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:sked/agent/connection/agent_credential_store.dart';
import 'package:sked/agent/store/agent_store_cutover.dart';
import 'package:sked/agent/store/legacy_operation_reconciliation.dart';
import 'package:sked/agent/provider/provider.dart';
import 'package:sked/models/timetable_models.dart';

import '../../support/workspace_harness.dart';

// These snapshots were generated by f28cf82d's actual Agent tool, mutation and
// edit-and-redo paths. The first save precedes the main inverse; the second has
// its durable receipt but the chat's owner-progress save failed. Neither ticket
// nor receipt digest is reconstructed with the implementation under test.
const _fixtureCommit = 'f28cf82d44ce9feac909fdb6c4c600d6dbba3b71';
const _retiredPreferences = [
  'maxModelRounds',
  'maxToolCalls',
  'maxTotalTokens',
];

class _MainStorage extends WorkspaceMemoryStorage {
  _MainStorage(super.data) : _inverseIds = _inverses(data);
  final Set<String> _inverseIds;
  int committedInverses = 0;

  static Set<String> _inverses(AppData data) => {
    for (final receipt in data.applicationLedger!.receipts)
      if (receipt.result['undoBatchId'] != null) receipt.operationId,
  };

  @override
  Future<void> save(AppData value) async {
    await super.save(value);
    final ids = _inverses(value);
    committedInverses += ids.difference(_inverseIds).length;
    _inverseIds.addAll(ids);
  }
}

class _NoModel extends ProviderClient {
  int requests = 0;

  @override
  Stream<ProviderEvent> stream(
    ProviderRequest request, {
    required String apiKey,
    ProviderCancellationToken? cancellation,
  }) async* {
    requests++;
    throw StateError('Startup recovery must not start the model.');
  }
}

void _expectNoRetiredPreferences(AppData data) {
  final settings = data.agentSettings.toJson();
  for (final key in _retiredPreferences) {
    expect(settings, isNot(contains(key)));
  }
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  for (final inverseAlreadyApplied in [false, true]) {
    test('startup recovers a pre-upgrade Agent preference ticket with '
        'inverseAlreadyApplied=$inverseAlreadyApplied', () async {
      final stage = inverseAlreadyApplied ? 'after_inverse' : 'before_inverse';
      final fixture = jsonDecode(
        await File(
          'test/agent/history/fixtures/legacy_agent_preferences_$stage.json',
        ).readAsString(),
      ) as Map<String, dynamic>;
      expect(fixture['sourceCommit'], _fixtureCommit);
      final rawSettings = (fixture['main'] as Map)['agentSettings'] as Map;
      for (final key in _retiredPreferences) {
        expect(rawSettings, contains(key));
      }
      final initial = AppData.decode(jsonEncode(fixture['main']));
      _expectNoRetiredPreferences(initial);
      expect(
        initial.agentSettings.systemInstructions,
        inverseAlreadyApplied
            ? 'Original workflow guidance.'
            : 'Updated workflow guidance.',
      );
      final mainStorage = _MainStorage(initial);
      final archive = Map<String, Object?>.from(
        fixture['conversations'] as Map,
      );
      final prior = (archive['conversations'] as List).single as Map;
      final batch = (prior['redoBatches'] as List).single as Map;
      final ticket = (batch['tickets'] as List).single as Map;
      final originalId = (ticket['operationIds'] as List).single as String;
      final originalReceipt = initial.applicationLedger!.receipts
          .singleWhere((receipt) => receipt.operationId == originalId)
          .toJson();
      final evidence = LegacyAgentCutoverEvidence(
        archives: [archive],
        mirrored: true,
        pendingHistoryBatch: fixture['pendingHistoryBatch'] as String,
      );
      final provider = _NoModel();
      // Exercise the one-time cutover reconciler with original saved tickets.
      final app = await workspaceProvider(
        storage: mainStorage,
        agentCredentialStore: MemoryAgentCredentialStore(),
        agentProvider: provider,
      );
      addTearDown(() async {
        await app.agent.quiesce();
        app.dispose();
      });
      Future<void> reconcile() async {
        await reconcileLegacyAgentOperations(
          evidence: evidence,
          mutations: app.agent.mutations,
          readCommittedData: () => app.session.committedData,
          reconcileExternal: (_) async =>
              throw StateError('No external write expected'),
        );
      }

      await reconcile();
      await reconcile();
      expect(provider.requests, 0);
      expect(app.agent.conversations.conversations, isEmpty);
      final restored = app.session.committedData;
      expect(
        restored.agentSettings.systemInstructions,
        'Original workflow guidance.',
      );
      expect(restored.agentSettings.historyRetentionDays, 30);
      _expectNoRetiredPreferences(restored);
      _expectNoRetiredPreferences(AppData.decode(mainStorage.data.encode()));
      final inverseReceipts = restored.applicationLedger!.receipts.where(
        (receipt) => receipt.result['undoBatchId'] == batch['id'],
      );
      expect(inverseReceipts, hasLength(1));
      expect(inverseReceipts.single.result['undoOperationIds'], [originalId]);
      expect(mainStorage.committedInverses, inverseAlreadyApplied ? 0 : 1);
      expect(
        restored.applicationLedger!.receipts
            .singleWhere((receipt) => receipt.operationId == originalId)
            .toJson(),
        originalReceipt,
      );

      final savedData = mainStorage.data.encode();
      await reconcile();
      expect(mainStorage.data.encode(), savedData);
      expect(mainStorage.committedInverses, inverseAlreadyApplied ? 0 : 1);
      expect(provider.requests, 0);
    });
  }
}
